+import type { Order } from "./orders.ts";
+import { findUser } from "./users.ts";
+
+export function receiptHeader(order: Order): string {
+  const user = findUser(order.userId)!;
+  return `Order ${order.id} for ${user.name} <${user.email}>, ${order.totalCents} cents`;
+}
